#!/bin/bash
# Flash the mAgent ESP32-S3 firmware (bootloader + partition table + app).
# Usage: ./flash-s3.sh [--port /dev/cu.usbmodemXXX]
#
# FIX (2026-09-15): the partition table is taken from the source CSV
# (`partitions.s3.csv`) and handed to espflash directly. Previously this
# script flashed `$PIO_OUT/partitions.bin`, which is a **stale copy**
# generated by an earlier PlatformIO run — the ESP-IDF/ninja build only
# refreshes `esp-idf/partition_table/partition_table_bin`, so the copy at the
# build root can lag by weeks. On the 4 MB S3 board that stale table had a
# 1 MB factory partition while the app image is ~1.5 MB, so the bootloader
# rejected the image ("Image length 1549152 doesn't fit in partition length
# 1048576") and the board sat in a boot loop. The CSV is the single source of
# truth (it is what `sdkconfig.defaults` points at via
# `CONFIG_PARTITION_TABLE_CUSTOM_FILENAME`).
set -euo pipefail

CHIP="esp32s3"
BAUD="${BAUD:-460800}"
PORT="${PORT:-/dev/cu.usbmodem101}"
if [[ "${1:-}" == "--port" && -n "${2:-}" ]]; then PORT="$2"; fi

DIR="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$DIR/../.." && pwd)"
cd "$DIR"

TGT="$REPO/target/xtensa-esp32s3-espidf/release"
ELF="$TGT/magent-esp32-app"
PART_CSV="$DIR/partitions.s3.csv"

# 1) Build (idempotent)
./build-s3.sh

# 2) Locate the latest esp-idf-sys build (bootloader.bin)
OUT="$(ls -dt "$REPO"/target/xtensa-esp32s3-espidf/release/build/esp-idf-sys-*/out/esp-idf/.pio/build/release 2>/dev/null | head -1)"
[ -n "$OUT" ] || { echo "error: no esp-idf-sys build dir"; exit 1; }
BOOT="$OUT/bootloader.bin"
[ -f "$BOOT" ] || { echo "error: bootloader.bin not found"; exit 1; }
[ -f "$PART_CSV" ] || { echo "error: $PART_CSV not found"; exit 1; }

# 3) Flash bootloader @0x0, partition table @0x8000 (from the CSV), app @0x10000.
#    espflash converts the Xtensa ELF itself (esptool's elf2image chokes on the
#    .literal/.text layout of this image — see BOARDS.md).
echo "Flashing ${CHIP} on ${PORT} @${BAUD}:"
echo "  bootloader:     $BOOT"
echo "  partition table: $PART_CSV"
espflash flash \
  --chip "$CHIP" \
  --port "$PORT" \
  --baud "$BAUD" \
  --bootloader "$BOOT" \
  --partition-table "$PART_CSV" \
  "$ELF"

echo ""
echo "Done. Reset the board and watch the serial console (115200)."
